'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['runSteps']);
assert.strictEqual(typeof api.runSteps, 'function');

(async () => {
  assert.deepStrictEqual(await api.runSteps([]), []);

  const events = [];
  let releaseFirst;
  const firstGate = new Promise(resolve => { releaseFirst = resolve; });
  const steps = [
    async () => {
      events.push('first:start');
      await firstGate;
      events.push('first:end');
      return 'one';
    },
    () => {
      events.push('second');
      return 2;
    },
    async () => {
      events.push('third');
      return undefined;
    }
  ];
  const originalSteps = steps.slice();
  const running = api.runSteps(steps);
  assert.ok(running instanceof Promise);
  await Promise.resolve();
  assert.deepStrictEqual(events, ['first:start']);
  releaseFirst();
  assert.deepStrictEqual(await running, ['one', 2, undefined]);
  assert.deepStrictEqual(events, ['first:start', 'first:end', 'second', 'third']);
  assert.deepStrictEqual(steps, originalSteps);

  let validationRuns = 0;
  await assert.rejects(
    api.runSteps([() => { validationRuns += 1; }, null, () => { validationRuns += 1; }]),
    TypeError
  );
  assert.strictEqual(validationRuns, 0);
  await assert.rejects(api.runSteps(null), TypeError);
  await assert.rejects(api.runSteps({}), TypeError);

  const syncFailure = new Error('sync failure');
  const syncEvents = [];
  await assert.rejects(api.runSteps([
    () => { syncEvents.push('before'); return 1; },
    () => { syncEvents.push('failure'); throw syncFailure; },
    () => { syncEvents.push('after'); return 3; }
  ]), error => error === syncFailure);
  assert.deepStrictEqual(syncEvents, ['before', 'failure']);

  const asyncFailure = new Error('async failure');
  const asyncEvents = [];
  await assert.rejects(api.runSteps([
    async () => { asyncEvents.push('before'); return 1; },
    () => { asyncEvents.push('failure'); return Promise.reject(asyncFailure); },
    () => { asyncEvents.push('after'); return 3; }
  ]), error => error === asyncFailure);
  assert.deepStrictEqual(asyncEvents, ['before', 'failure']);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

